-- ==========================================================
-- SCRIPT POSTGRESQL CHUẨN CHO DỰ ÁN WEB GẠCH THUẬN LỢI
-- (Tương thích 100% với .NET 9 EF Core & Npgsql)
-- ==========================================================

-- 1. AdminUser
CREATE TABLE IF NOT EXISTS "AdminUser" (
    "Id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Username" VARCHAR(50) NOT NULL,
    "PasswordHash" VARCHAR(255) NOT NULL
);
CREATE UNIQUE INDEX IF NOT EXISTS "IX_AdminUser_Username" ON "AdminUser" ("Username");

-- 2. Product
CREATE TABLE IF NOT EXISTS "Product" (
    "Id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Name" VARCHAR(150) NOT NULL,
    "Slug" VARCHAR(150) NOT NULL,
    "ShortDescription" VARCHAR(500) NULL,
    "Description" TEXT NULL,
    "Length" NUMERIC(10,2) NULL,
    "Width" NUMERIC(10,2) NULL,
    "Height" NUMERIC(10,2) NULL,
    "CompressionStrength" NUMERIC(10,2) NULL,
    "FlexuralStrength" NUMERIC(10,2) NULL,
    "BrickGrade" VARCHAR(50) NULL,
    "IsFeatured" BOOLEAN NOT NULL DEFAULT FALSE,
    "DisplayOrder" INT NOT NULL DEFAULT 0,
    "IsActive" BOOLEAN NOT NULL DEFAULT TRUE,
    "CreatedAt" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "UpdatedAt" TIMESTAMPTZ NULL
);
CREATE UNIQUE INDEX IF NOT EXISTS "IX_Product_Slug" ON "Product" ("Slug");

-- 3. ProductImage
CREATE TABLE IF NOT EXISTS "ProductImage" (
    "Id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "ProductId" INT NOT NULL,
    "ImagePath" VARCHAR(500) NOT NULL,
    "IsThumbnail" BOOLEAN NOT NULL DEFAULT FALSE,
    "AltText" VARCHAR(255) NULL,
    "DisplayOrder" INT NOT NULL DEFAULT 0,
    CONSTRAINT "FK_ProductImage_Product" FOREIGN KEY("ProductId") REFERENCES "Product"("Id") ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS "IX_ProductImage_ProductId" ON "ProductImage" ("ProductId");

-- 4. Project
CREATE TABLE IF NOT EXISTS "Project" (
    "Id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Name" VARCHAR(255) NOT NULL,
    "Slug" VARCHAR(255) NOT NULL,
    "ShortDescription" VARCHAR(500) NULL,
    "Description" TEXT NULL,
    "Location" VARCHAR(255) NULL,
    "CompletedDate" DATE NULL,
    "DisplayOrder" INT NOT NULL DEFAULT 0,
    "IsFeatured" BOOLEAN NOT NULL DEFAULT FALSE,
    "IsActive" BOOLEAN NOT NULL DEFAULT TRUE,
    "CreatedAt" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "UpdatedAt" TIMESTAMPTZ NULL
);
CREATE UNIQUE INDEX IF NOT EXISTS "IX_Project_Slug" ON "Project" ("Slug");

-- 5. ProjectImage
CREATE TABLE IF NOT EXISTS "ProjectImage" (
    "Id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "ProjectId" INT NOT NULL,
    "ImagePath" VARCHAR(500) NOT NULL,
    "IsThumbnail" BOOLEAN NOT NULL DEFAULT FALSE,
    "DisplayOrder" INT NOT NULL DEFAULT 0,
    CONSTRAINT "FK_ProjectImage_Project" FOREIGN KEY("ProjectId") REFERENCES "Project"("Id") ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS "IX_ProjectImage_ProjectId" ON "ProjectImage" ("ProjectId");

-- 6. News
CREATE TABLE IF NOT EXISTS "News" (
    "Id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Title" VARCHAR(250) NOT NULL,
    "Slug" VARCHAR(250) NOT NULL,
    "ThumbnailPath" VARCHAR(500) NULL,
    "Summary" TEXT NULL,
    "Content" TEXT NULL,
    "PublishedAt" TIMESTAMPTZ NULL,
    "IsActive" BOOLEAN NOT NULL DEFAULT TRUE,
    "CreatedAt" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "UpdatedAt" TIMESTAMPTZ NULL
);
CREATE UNIQUE INDEX IF NOT EXISTS "IX_News_Slug" ON "News" ("Slug");

-- 6.1 NewsSection
CREATE TABLE IF NOT EXISTS "NewsSection" (
    "Id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "NewsId" INT NOT NULL,
    "Question" VARCHAR(500) NULL,
    "Answer" TEXT NULL,
    "DisplayOrder" INT NOT NULL DEFAULT 0,
    CONSTRAINT "FK_NewsSection_News" FOREIGN KEY("NewsId") REFERENCES "News"("Id") ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS "IX_NewsSection_NewsId" ON "NewsSection" ("NewsId");

-- 6.2 NewsImage
CREATE TABLE IF NOT EXISTS "NewsImage" (
    "Id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "NewsId" INT NOT NULL,
    "NewsSectionId" INT NULL,
    "ImagePath" VARCHAR(500) NOT NULL,
    "Caption" VARCHAR(500) NULL,
    "DisplayOrder" INT NOT NULL DEFAULT 0,
    CONSTRAINT "FK_NewsImage_News" FOREIGN KEY("NewsId") REFERENCES "News"("Id") ON DELETE CASCADE,
    CONSTRAINT "FK_NewsImage_NewsSection" FOREIGN KEY("NewsSectionId") REFERENCES "NewsSection"("Id") ON DELETE SET NULL
);
CREATE INDEX IF NOT EXISTS "IX_NewsImage_NewsId" ON "NewsImage" ("NewsId");
CREATE INDEX IF NOT EXISTS "IX_NewsImage_NewsSectionId" ON "NewsImage" ("NewsSectionId");

-- 7. Partner
CREATE TABLE IF NOT EXISTS "Partner" (
    "Id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Name" VARCHAR(150) NOT NULL,
    "LogoPath" VARCHAR(500) NULL,
    "Website" VARCHAR(255) NULL,
    "DisplayOrder" INT NOT NULL DEFAULT 0,
    "IsActive" BOOLEAN NOT NULL DEFAULT TRUE
);

-- 8. ContactInfo
CREATE TABLE IF NOT EXISTS "ContactInfo" (
    "Id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "CompanyName" VARCHAR(255) NOT NULL,
    "Address" VARCHAR(500) NULL,
    "Phone" VARCHAR(20) NULL,
    "Email" VARCHAR(100) NULL,
    "Facebook" VARCHAR(255) NULL,
    "Zalo" VARCHAR(255) NULL,
    "Tiktok" VARCHAR(255) NULL,
    "GoogleMapEmbed" TEXT NULL,
    "WorkingHours" VARCHAR(255) NULL
);

-- 9. ContactRequest
CREATE TABLE IF NOT EXISTS "ContactRequest" (
    "Id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "FullName" VARCHAR(100) NOT NULL,
    "Phone" VARCHAR(20) NOT NULL,
    "Email" VARCHAR(100) NULL,
    "Content" TEXT NOT NULL,
    "IsRead" BOOLEAN NOT NULL DEFAULT FALSE,
    "CreatedAt" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP
);

-- ==========================================================
-- DỮ LIỆU BAN ĐẦU (SEED DATA CHO POSTGRESQL)
-- ==========================================================

